window.AQ_RUQA={"q0.mp3":{"a":"Aquora — это полноценная умная система управления оросительной и питьевой водой в масштабах целой страны. Она охватывает весь цикл: от регистрации и посевов до графика полива, датчиков, начислений и оплаты — вручную или просто голосом.","q":["что такое аквора","что такое aquora","расскажи про аквору","что это за система","аквора это что","что умеет aquora"]},"q1.mp3":{"a":"Дашборд — это вся страна на одном экране: активные лицевые счета, вода, поданная сегодня, сколько собрано оплат и сколько потеряно в виде неучтённой воды — всё в реальном времени.","q":["что показывает дашборд","дашборд","главный экран","что на главной панели","что видно на дашборде","панель управления"]},"q2.mp3":{"a":"Неучтённая вода — это разница между объёмом, поданным из источника, и объёмом, реально выставленным к оплате пользователям. Aquora измеряет её автоматически, чтобы выявлять утечки и хищения воды.","q":["что такое неучтённая вода","неучтённая вода","что значит неучтенная вода","что такое потери воды","non revenue water что это"]},"q3.mp3":{"a":"Система снижает затраты: начисляет по реальным объёмам со счётчиков, мгновенно выявляет утечки и хищения воды и оптимизирует подачу — меньше воды теряется, больше денег собирается.","q":["как система экономит деньги","как система экономит","какая экономия от системы","как снизить затраты на воду","в чём выгода системы"]},"q4.mp3":{"a":"Интерфейс, голосовой ассистент и документы работают на любом языке, включая арабский с письмом справа налево, а распознавание речи поддерживает более тысячи шестисот языков.","q":["какие языки поддерживаются","на каких языках работает","какие языки поддерживает система","языки","есть ли русский язык"]},"q5.mp3":{"a":"Внедрение модульное и быстрое. Мы наносим каналы на карту, подключаем датчики и регистрируем хозяйства — и регион может заработать уже через несколько недель.","q":["сколько времени занимает внедрение","как долго внедрять","сроки внедрения","как быстро можно запустить","сколько длится внедрение"]},"q6.mp3":{"a":"Каждое хозяйство и домохозяйство регистрируется вместе с участками и площадью. Их может добавить оператор, или люди регистрируются сами — просто голосом, через WhatsApp, звонок или USSD.","q":["как регистрируются водопользователи","регистрация водопользователей","водопользователи","как зарегистрировать водопользователя","как добавить водопользователя"]},"q7.mp3":{"a":"Да. Фермер может зарегистрироваться сам — голосом или через WhatsApp, а оператор просто подтверждает регистрацию, так что идти в офис не нужно.","q":["могут ли фермеры зарегистрироваться сами","может ли фермер сам зарегистрироваться","самостоятельная регистрация","регистрация через whatsapp","как фермеру зарегистрироваться"]},"q8.mp3":{"a":"Культура определяет норму воды. Хлопку, пшенице, рису и люцерне нужно разное количество воды, поэтому культура и дата посева задают весь план полива.","q":["почему важна культура","зачем указывать культуру","посевы","как культура влияет на полив","культуры"]},"q9.mp3":{"a":"Карта показывает сеть в реальном времени: водохранилище, магистральный канал и его отводы, затворы и участки, расход по каждому каналу и положение затворов, а при тревоге датчика — пульсирующую метку.","q":["что показывает карта","карта","что на карте","карта каналов","что видно на карте"]},"q10.mp3":{"a":"На экране «Заявки» пользователь запрашивает воду — голосом или кнопкой «Новая заявка», и система превращает заявку в декадный план полива.","q":["как заказать воду","как подать заявку на воду","заявки","как создать заявку","заявка на воду"]},"q11.mp3":{"a":"Да. Достаточно сказать, сколько воды нужно и для какого участка, и Aquora сама создаст заявку, план и счёт.","q":["можно ли заказать воду голосом","заявка голосом","можно ли подать заявку голосом","голосовая заявка на воду"]},"q12.mp3":{"a":"Aquora берёт нетто-норму воды каждой культуры на каждую декаду в её гидромодульном районе, делит на КПД системы, чтобы получить брутто-объём, и строит полный сезонный график, который пересчитывается при изменении условий.","q":["как строится план полива","план полива","как рассчитывается план полива","как формируется график полива","график полива"]},"q13.mp3":{"a":"Хлопку нужно около двенадцати поливов за сезон, а рису — около двадцати. Система рассчитывает точный объём для каждого полива, так что никому не нужно считать вручную.","q":["сколько воды нужно хлопку","сколько поливов нужно хлопку","норма воды для хлопка","сколько воды нужно рису"]},"q14.mp3":{"a":"Каждая зона получает сезонный лимит воды. Система сверяет его с реальным спросом и подачей, поэтому руководители всегда знают, сколько воды ещё доступно, пока её не стало не хватать.","q":["что такое лимиты воды","лимиты воды","лимит воды","что такое лимит","как работают лимиты"]},"q15.mp3":{"a":"Каждое подключение измеряется в реальном времени: входящая питьевая вода, отводимые стоки, полив, а также расход в каналах, уровни воды и влажность почвы — данные поступают каждую секунду.","q":["что измеряют датчики","датчики","что показывают датчики","какие датчики есть","что меряют сенсоры"]},"q16.mp3":{"a":"Да. Входящая питьевая вода и отводимые стоки измеряются раздельно для каждого домохозяйства в реальном времени, поэтому начисления идут по фактическому потреблению, а не по оценке.","q":["учитывается ли питьевая вода","есть ли счётчик на питьевую воду","питьевая вода","счётчики питьевой воды","измеряется ли питьевая вода"]},"q17.mp3":{"a":"Система следит за расходом каждую секунду, поэтому замечает необычный всплеск — например, в три часа ночи, — автоматически закрывает клапан и уведомляет пользователя ещё до того, как будет нанесён ущерб.","q":["как система обнаруживает утечку","утечка","как найти утечку","обнаружение утечек","что будет при утечке"]},"q18.mp3":{"a":"Да. Просто скажите ассистенту, что вас не будет с первого по пятнадцатое, — клапан закроется и снова откроется в день вашего возвращения.","q":["можно ли приостановить воду когда меня нет","приостановить подачу воды","я уезжаю что с водой","пауза подачи воды","отключить воду на время отъезда"]},"q19.mp3":{"a":"Да. Домохозяйство может открыть или закрыть свой кран питьевой воды прямо с телефона, а система подтвердит это и продолжит измерение в реальном времени.","q":["можно ли закрыть кран с телефона","закрыть домашний кран с телефона","перекрыть воду дома с телефона","управление краном с телефона"]},"q22.mp3":{"a":"Счёт формируется по реальному измеренному объёму, без догадок. После подачи воды и подписания акта приёма воды измеренный объём умножается на тариф.","q":["как рассчитывается счёт","как считается счет","начисления","как формируется счёт","расчёт оплаты за воду"]},"q23.mp3":{"a":"Долг появляется только после подачи воды и обработки подписанного акта приёма воды и рассчитывается как фактический измеренный объём, умноженный на тариф.","q":["когда появляется долг","когда возникает задолженность","откуда долг","задолженность","как считается долг"]},"q24.mp3":{"a":"Пользователи платят с телефона через банк на свой лицевой счёт, а система автоматически сверяет каждый платёж и гасит долг в реальном времени.","q":["как оплатить","как платить за воду","оплата","как оплатить счёт","куда платить"]},"q25.mp3":{"a":"Любой вид — заявки, водный баланс, план и факт, сборы и потери — можно отфильтровать и выгрузить в Excel или PDF одним кликом, для полной прозрачности.","q":["какие отчёты можно получить","отчёты","какие есть отчеты","выгрузка в excel","экспорт отчётов"]},"q26.mp3":{"a":"Система сравнивает водный баланс каждого канала со спутниковыми признаками полива на участках без выделенного лимита и выдаёт инспекторам ранжированный список самых подозрительных случаев.","q":["как система находит потери воды","потери воды","как найти потери воды","где теряется вода","выявление потерь"]},"q27.mp3":{"a":"Сочетая показания счётчиков и расход в каналах в реальном времени со спутниковыми снимками, система замечает воду, использованную там, где её никто не заказывал, и отмечает такие случаи для проверки.","q":["как выявить хищение воды","хищение воды","кража воды","как поймать воровство воды","как обнаружить кражу воды"]},"q28.mp3":{"a":"Это офлайн-приложение для инспекторов и ремонтных бригад: задания, фото, акты о нарушениях и электронные подписи, с автоматической синхронизацией при восстановлении связи.","q":["что такое приложение для полевых проверок","полевое приложение","приложение инспектора","инспекции","приложение для инспекторов"]},"q29.mp3":{"a":"Да. Полевое приложение и локальные контроллеры продолжают работать без связи и автоматически синхронизируются, как только связь восстановится.","q":["работает ли приложение офлайн","приложение без интернета","офлайн режим","работает ли без связи"]},"q30.mp3":{"a":"Каждый фермер получает персональные рекомендации в WhatsApp или голосом, например: полейте участок три в четверг объёмом 900 м³ и пропустите следующую очередь, потому что ожидается дождь.","q":["какие советы получают фермеры","рекомендации фермерам","советы фермеру","приложение фермера","что подсказывает система фермеру"]},"q31.mp3":{"a":"Aquora измеряет и подтверждает сэкономленную воду и энергию и готовит отчёты для доноров и климатических фондов — с возможностью получения водных или углеродных кредитов.","q":["какая есть климатическая отчётность","климатическая отчетность","климат","углеродные кредиты","климатический модуль"]},"q32.mp3":{"a":"С явного согласия фермера, которое можно отозвать, история водопользования передаётся банкам и страховщикам для кредитного скоринга и страхования от засухи — это новый источник дохода.","q":["как работают финансовые сервисы","финансовые сервисы","кредиты для фермеров","страхование от засухи","кредитный скоринг"]},"q33.mp3":{"a":"Для стран Персидского залива Aquora управляет лицензиями на скважины, счётчиками на скважинах и распределением очищенной воды для ферм и озеленения.","q":["что насчёт очищенных стоков и подземных вод","очищенные сточные воды","подземные воды","скважины","страны залива"]},"q34.mp3":{"a":"Система даёт общий водный баланс для стран одного речного бассейна — Центральной Азии, Нила или водоносных горизонтов Залива, — чтобы стороны, делящие одну реку, могли доверять цифрам.","q":["что такое трансграничный бассейн","трансграничный бассейн","бассейн реки","общий водный баланс стран","трансграничные реки"]},"q35.mp3":{"a":"Каждый агент выполняет реальную работу: помощник фермера, второй пилот для ассоциации, второй пилот диспетчера, аналитик министерства, агент аномалий, следящий за датчиками, и ИИ для документов, который переносит отсканированные бумаги в реестр.","q":["что делают ии агенты","ии агенты","расскажи про слой ии","искусственный интеллект","объясни слой ии","агенты ии"]},"q36.mp3":{"a":"Да. Любое физическое действие — клапан или затвор — подтверждает человек, каждое решение ИИ записывается в журнал, пользователям сообщают, что они говорят с ИИ, а правительства могут запускать модель внутри страны.","q":["безопасен ли ии","насколько безопасен ии","безопасность ии","можно ли доверять ии"]},"q37.mp3":{"a":"Водопотребление культур — из FAO WaPOR каждые десять дней, снимки — с Sentinel-2 и Landsat, картирование культур — Prithvi и AlphaEarth, погода — ECMWF, а речь более чем на тысяче шестистах языках — Meta Omnilingual.","q":["какие спутниковые данные используются","спутниковые данные","спутники","откуда спутниковые снимки","какие спутники используете"]},"q38.mp3":{"a":"Страновые пакеты настраивают язык, тарифы, платежи и законодательство без кода; плюс открытый API, ролевые права доступа, офлайн мобильное приложение, полный журнал аудита, доступность и надёжная безопасность.","q":["какие возможности у платформы","возможности платформы","платформа","функции платформы","что есть в платформе"]},"q39.mp3":{"a":"Aquora построена с учётом требований NIS2 к цепочкам поставок, Закона о киберустойчивости, правил AI Act для систем высокого риска, права на доступ к данным датчиков по Data Act и GDPR с согласием на использование голоса.","q":["как вы соответствуете правилам ес","требования евросоюза","соответствие gdpr","nis2","европейские правила","регулирование ес"]},"q40.mp3":{"a":"Дорожная карта: реальное ядро и выявление потерь в первые шесть месяцев, слой ИИ и спутниковые данные к двенадцати месяцам, открытый маркетплейс и бассейновый вид к двадцати четырём.","q":["что в дорожной карте","дорожная карта","планы развития","что дальше по плану","роадмап"]},"q41.mp3":{"a":"Да. Все данные пользователей, начислений и потребления шифруются; есть единый вход, двухфакторная аутентификация, резервные копии и готовность к ISO 27001.","q":["защищены ли мои данные","безопасность данных","мои данные в безопасности","шифруются ли данные"]},"q42.mp3":{"a":"Доступ ролевой для каждого уровня водной иерархии, с цепочками согласования, поэтому каждый пользователь видит только то, что нужно для его работы.","q":["кто что видит","права доступа","роли пользователей","кто имеет доступ","разграничение доступа"]},"q43.mp3":{"a":"Да. Локальные контроллеры кэшируют данные и продолжают работать офлайн, а когда связь возвращается, всё синхронизируется автоматически.","q":["может ли система работать без интернета","работа без интернета","без интернета","что если нет интернета"]},"q44.mp3":{"a":"Системой можно управлять просто голосом: заказать воду, приостановить подачу, закрыть домашний кран или сообщить об утечке — ассистент всё сделает и подтвердит.","q":["как работает голосовое управление","голосовое управление","управление голосом","голосовой ассистент","голос"]},"q45.mp3":{"a":"Здравствуйте! Я ассистент Aquora. Помогу со всей системой водоснабжения: регистрацией, посевами, графиком полива, датчиками, начислениями и оплатой. Что вас интересует?","q":["привет","здравствуйте","добрый день","алло","здравствуй","доброе утро"]},"q46.mp3":{"a":"Я ассистент Aquora. Я управляю всей умной системой водоснабжения и объясняю её работу — вручную или просто голосом.","q":["кто ты","ты кто","кто вы","с кем я говорю","представься"]},"q47.mp3":{"a":"Я могу заказать воду, построить план полива, считать показания датчиков, обнаружить утечки, закрыть ваш домашний кран, рассчитать счета, принять оплату и ответить на вопросы — всё голосом.","q":["что ты умеешь","что ты можешь","чем ты можешь помочь","твои возможности","что умеет ассистент"]},"q48.mp3":{"a":"Цена зависит от размера сети и выбранных модулей. Система модульная: вы начинаете с ядра и платите по мере роста, а экономия от устранения потерь обычно окупает её.","q":["сколько это стоит","цена","стоимость системы","сколько стоит aquora","сколько стоит аквора","какая цена","сколько стоит система","сколько стоит ваша система","сколько это будет стоить"]},"q49.mp3":{"a":"Aquora создана нашей командой как платформа, которую можно адаптировать к потребностям любой страны в оросительной и питьевой воде без переписывания ядра.","q":["кто это сделал","кто создал систему","кто разработал aquora","кто разработал аквору","кто разработчик"]},"q50.mp3":{"a":"Это рабочее демо платформы. Основные модули реальные, а каждая страна получает свою настроенную версию.","q":["это реальный продукт","это настоящий продукт","это демо","это работает по настоящему","это прототип"]},"q51.mp3":{"a":"Да. Aquora рассчитана на любой масштаб — от одной ассоциации водопользователей до национального министерства — на том же ядре и страновых пакетах.","q":["можно ли масштабировать на всю страну","масштабирование","подойдёт ли для всей страны","масштаб страны"]},"q52.mp3":{"a":"Нужны счётчики и датчики расхода на подключениях и каналах, а также клапаны там, где требуется дистанционное управление. Aquora не привязана к производителю и подключается по MQTT, LoRaWAN или OPC-UA.","q":["какое оборудование нужно","оборудование","какое железо нужно","что нужно установить","какие счётчики нужны"]},"q53.mp3":{"a":"Для измерения в реальном времени и автоматического управления клапанами устанавливаются IoT-счётчики и датчики, но система работает и с ручными показаниями там, где датчиков пока нет.","q":["нужно ли устанавливать датчики","обязательно ли ставить датчики","можно без датчиков","ручные показания"]},"q54.mp3":{"a":"Очень точные. IoT-счётчики и датчики отслеживают расход, уровни и влажность почвы в реальном времени, а начисления идут по реальному измеренному объёму, без оценок.","q":["насколько точны данные","точность данных","точные ли данные","насколько точно измерение"]},"q55.mp3":{"a":"Безопасность многоуровневая: шифрование, единый вход, двухфакторная аутентификация, ролевой доступ, журналы аудита и резервные копии, с готовностью к ISO 27001.","q":["можно ли взломать систему","взлом","кибербезопасность","защита от хакеров","безопасность"]},"q56.mp3":{"a":"Данные принадлежат заказчику. Фермеры также имеют право на доступ к данным своих датчиков, и ничего не передаётся третьим лицам без явного согласия.","q":["кому принадлежат данные","владелец данных","чьи это данные","кто владеет данными"]},"q57.mp3":{"a":"Да. Есть открытый API и маркетплейс коннекторов для производителей оборудования, банков, ERP-систем и поставщиков спутниковых данных.","q":["можно ли интегрировать с нашими системами","интеграция","есть ли api","интеграция с другими системами","открытый api"]},"q58.mp3":{"a":"Платежи могут идти через банк на лицевой счёт, а платформа поддерживает такие каналы, как SEPA, карты, Mada и SADAD, а также мобильные деньги вроде M-Pesa и MTN.","q":["какие способы оплаты поддерживаются","способы оплаты","чем можно оплатить","оплата картой","мобильные платежи"]},"q59.mp3":{"a":"Каждое начисление строится по реальному измеренному объёму после подписанного акта, каждое действие записывается в журнал, а отчёты полностью выгружаются — места для скрытых корректировок нет.","q":["как система снижает коррупцию","коррупция","снижение коррупции","прозрачность начислений"]},"q60.mp3":{"a":"В отличие от бумажных журналов, Aquora строит графики автоматически, измеряет воду в реальном времени, мгновенно останавливает утечки и ведёт полный журнал аудита — экономя время, воду и споры.","q":["чем это лучше бумаги","чем лучше бумажного учёта","зачем это если есть бумага","преимущества перед бумагой"]},"q61.mp3":{"a":"Во время засухи система отслеживает оставшийся лимит каждой зоны, контролирует реальный расход в каналах и помогает диспетчерам справедливо распределять воду с помощью сценариев «что если».","q":["что делать при засухе","засуха","как система работает в засуху","как справиться с засухой","дефицит воды"]},"q62.mp3":{"a":"Да. Система работает через WhatsApp, Telegram, голосовой звонок или USSD, так что даже с простого телефона можно заказать воду, посмотреть график и получить совет.","q":["работает ли на любом телефоне","на любом телефоне","кнопочный телефон","работает ли через telegram","работает ли через whatsapp"]},"q63.mp3":{"a":"Есть режим для людей с низкой грамотностью — с иконками и голосом, крупными кнопками и письмом справа налево, так что пользоваться может любой, кто умеет говорить.","q":["что насчёт неграмотных пользователей","неграмотные пользователи","если человек не умеет читать","для неграмотных","низкая грамотность"]},"q64.mp3":{"a":"Да. Интерфейс, голос и документы поддерживают арабский, включая раскладку справа налево, а для речи — более тысячи шестисот языков.","q":["поддерживается ли арабский","арабский язык","есть ли арабский","работает на арабском"]},"q65.mp3":{"a":"Пилот обычно занимает несколько недель: нанести каналы на карту, подключить датчики и зарегистрировать хозяйства в одном районе, а затем масштабировать на весь регион.","q":["сколько длится пилот","пилот","пилотный проект","сколько времени на пилот","как проходит пилот"]},"q66.mp3":{"a":"Подход следует реальным ирригационным проектам Всемирного банка и проверенным методам; каждое внедрение адаптируется и может начинаться с измеримого пилота.","q":["есть ли у вас рекомендации","референсы","примеры внедрения","есть ли отзывы","где это уже работает"]},"q67.mp3":{"a":"ИИ никогда не управляет физическими клапанами или затворами без подтверждения человека, каждое решение записывается в журнал, а пользователям всегда сообщают, что они говорят с ИИ.","q":["будет ли ии ошибаться","а если ии ошибётся","ошибки ии","ии может ошибиться"]},"q68.mp3":{"a":"В рамках GDPR мы проводим оценку воздействия на защиту данных, подписываем соглашения об обработке данных и берём добровольное согласие на использование голоса, а фермеры могут получать доступ к своим данным и управлять ими.","q":["как защищена моя приватность","конфиденциальность","защита персональных данных","приватность","gdpr"]},"q69.mp3":{"a":"Датчики фиксируют отключение питания на насосной станции, а диспетчерский центр перенаправляет поток или запускает резервные генераторы, чтобы поля не остались без воды.","q":["что будет если отключат электричество","отключение электричества","нет света","сбой питания насосной станции","пропало электричество"]},"q70.mp3":{"a":"Да. Реестр прав на воду поддерживает передачу или продажу квот между фермерами — как в проекте Всемирного банка в Марокко, — там, где для этого есть правовая основа.","q":["могут ли фермеры торговать водой","торговля водой","передача квот на воду","обмен водой между фермерами","продать воду соседу"]},"q71.mp3":{"a":"Климатический модуль формирует измеренные и подтверждённые отчёты о сэкономленной воде и энергии, готовые для доноров и климатических фондов, с возможностью получения углеродных или водных кредитов.","q":["как получить отчёт для доноров","отчёт для доноров","доноры","отчётность для климатических фондов"]},"q72.mp3":{"a":"Ассоциация водопользователей — это местная организация, которая управляет водой для своих членов. Она может установить фиксированный годовой взнос и является одним из уровней водной иерархии.","q":["что такое ассоциация водопользователей","что такое авп","авп","ассоциация водопользователей","членский взнос авп"]},"q73.mp3":{"a":"Да. Платформа поддерживает рассрочку и оплату по мере потребления и автоматически сверяет каждый платёж с вашим лицевым счётом.","q":["можно ли платить в рассрочку","рассрочка","оплата частями","можно платить частями"]},"q74.mp3":{"a":"Я использую распознавание речи более чем на тысяче шестистах языках, так что можете просто говорить со мной на своём языке — в приложении, в WhatsApp или по телефону.","q":["как ассистент меня понимает","как ты меня понимаешь","распознавание речи","понимаешь ли ты меня"]},"q75.mp3":{"a":"Боюсь, кофе — не моя работа! Но с водой я справлюсь: заявки, план полива, утечки, начисления и оплата. Что хотите сделать?","q":["а кофе она варит","сделай кофе","умеешь варить кофе","свари кофе"]},"q76.mp3":{"a":"Никакой магии — просто датчики в реальном времени, спутниковые данные и ИИ, работающие вместе, и человек, подтверждающий всё, что двигает клапан.","q":["это магия","это волшебство","как это работает магия","это какое-то волшебство"]},"q77.mp3":{"a":"Благодаря начислениям по реальным объёмам, выявлению хищений и утечек и оптимизации подачи государство собирает больше и теряет гораздо меньше воды.","q":["как система экономит деньги государству","выгода для государства","экономия для государства","что получит государство"]},"q78.mp3":{"a":"Любые культуры. Для каждого участка указываются культура и дата посева, и система применяет норму воды этой культуры — для хлопка, пшеницы, риса, люцерны, садов и других.","q":["какие культуры поддерживаются","какие культуры","список культур","поддерживает ли хлопок","какие посевы можно вести"]},"q79.mp3":{"a":"Да. Отчёты и дашборд показывают неучтённую воду и потери по каналам и зонам, так что видно, где именно исчезает вода.","q":["можно ли увидеть потери по зонам","потери по зонам","потери по каналам","где исчезает вода"]},"q81.mp3":{"a":"Цена может быть по подписке, за гектар или за подключение — как удобнее заказчику. Модель гибкая.","q":["это подписка или за гектар","бизнес-модель","бизнес модель","модель оплаты","saas или за гектар","как вы берёте деньги"]},"q83.mp3":{"a":"Большинство решений закрывают только одну часть — карту, счётчик или биллинг. Отличие Aquora — единая платформа, которая ведёт весь цикл от заявки до оплаты, со встроенным ИИ и спутниками.","q":["кто ваши конкуренты","конкуренты","чем вы отличаетесь от конкурентов","чем aquora лучше конкурентов","чем аквора лучше конкурентов"]},"q85.mp3":{"a":"Платформа построена на опыте реальных внедрений и следует проверенным методам Всемирного банка, а каждая новая страна начинает с измеримого пилота перед масштабированием.","q":["есть ли у вас пилоты или клиенты","клиенты","есть ли клиенты","кто уже пользуется","ваши заказчики"]},"q86.mp3":{"a":"Да. Благодаря страновым пакетам и темам оформления платформу можно брендировать и настраивать для каждого министерства или оператора без изменения ядра.","q":["можно ли white label","белая метка","можно ли под своим брендом","брендирование","своё оформление"]},"q87.mp3":{"a":"Мы привлекаем инвестиции, чтобы внедрить систему у первых заказчиков национального масштаба и расширить слои ИИ и спутниковых данных. Конкретный раунд можем обсудить напрямую.","q":["сколько вы привлекаете","инвестиции","раунд инвестиций","вы ищете инвесторов","какой раунд"]},"q88.mp3":{"a":"Да. Ради суверенитета данных вся платформа, включая модель ИИ, может работать внутри страны — при необходимости на государственной инфраструктуре.","q":["может ли государство разместить систему у себя","размещение в стране","суверенитет данных","свои сервера","хостинг в стране"]},"q89.mp3":{"a":"Измеряя и подтверждая сэкономленную воду и энергию, Aquora даёт доказательную базу для обязательств в области устойчивого развития и климата, с возможностью получения углеродных и водных кредитов.","q":["как это помогает климатическим целям","климатические цели","устойчивое развитие","цели по климату"]},"q90.mp3":{"a":"Система применяет собственную модель водных прав страны, её тарифы и лимиты, то есть реализует национальную политику, а не заменяет её.","q":["как это сочетается с национальной водной политикой","водная политика","национальное законодательство","водные права страны"]},"q91.mp3":{"a":"Да. Через открытый API система связывается с национальными реестрами ID и земельными кадастрами, поэтому хозяйства и владельцы сверяются с официальными записями.","q":["можно ли интегрировать с реестром удостоверений или кадастром","земельный кадастр","интеграция с кадастром","национальный реестр","проверка владельцев земли"]},"q92.mp3":{"a":"Каждое начисление основано на реальном измеренном объёме после подписанного акта, каждое действие записывается в журнал, все отчёты выгружаются — аудиторы могут отследить всё, и места для скрытых изменений нет.","q":["как это помогает бороться с коррупцией","борьба с коррупцией","антикоррупция","аудит начислений"]},"q93.mp3":{"a":"Современная веб-платформа с пространственной базой данных PostGIS, независимыми от производителя IoT-коннекторами и сервисами ИИ — всё доступно через открытый API.","q":["какой технологический стек","стек технологий","на чём написана система","какие технологии используются","архитектура"]},"q94.mp3":{"a":"И то и другое. Система работает в облаке, на собственных серверах заказчика или в государственном дата-центре — как требуют правила работы с данными у заказчика.","q":["это облако или на своих серверах","облако или локально","облачное решение","можно ли установить локально","on premise"]},"q95.mp3":{"a":"Платформа рассчитана на высокую доступность — с резервированием и резервными копиями, а локальные контроллеры поддерживают работу в поле, даже если центральная система ненадолго недоступна.","q":["какая у вас доступность","аптайм","надёжность системы","что если сервер упадёт","отказоустойчивость"]},"q96.mp3":{"a":"Мы импортируем существующие реестры, счётчики и записи начислений через API, а ИИ для документов переносит отсканированные записи в новую систему.","q":["как перенести наши старые данные","миграция данных","перенос данных","импорт старых данных","старые бумажные записи"]},"q97.mp3":{"a":"Полевые датчики потребляют мало энергии и обычно работают от солнечных панелей с резервным аккумулятором, а платформа отслеживает заряд батареи и прошивку каждого устройства.","q":["как питаются полевые датчики","питание датчиков","от чего работают датчики","батарея датчиков","солнечные панели"]},"q98.mp3":{"a":"Данные резервируются непрерывно с регулярными точками восстановления, а денежные таблицы защищаются перед каждым изменением.","q":["как часто делаются бэкапы","резервные копии","бэкапы","резервное копирование"]},"q99.mp3":{"a":"Платформа следует практикам ISO 27001 — шифрование, единый вход и двухфакторная аутентификация — и может проходить аудит для каждого внедрения.","q":["есть ли сертификаты безопасности","сертификация","iso 27001","сертификаты"]},"q100.mp3":{"a":"Совсем немного. Экраны повторяют реальный рабочий процесс, а голосовой ассистент подсказывает пользователям, так что оператор начинает продуктивно работать после короткого занятия.","q":["сколько обучения нужно операторам","обучение","обучение операторов","сложно ли научиться"]},"q101.mp3":{"a":"Мы обеспечиваем подключение, документацию и постоянную поддержку, а ассистент круглосуточно отвечает на повседневные вопросы.","q":["какую поддержку вы даёте","поддержка","техподдержка","служба поддержки"]},"q102.mp3":{"a":"Не проблема. Фермер может пользоваться простым телефоном через голосовой звонок или USSD, либо оператор может действовать от его имени.","q":["что если у фермера нет смартфона","нет смартфона","без смартфона","простой телефон","у фермера нет телефона"]},"q103.mp3":{"a":"Обратитесь в свою ассоциацию или к оператору. Поскольку каждое начисление привязано к измеренному объёму и подписанному акту, его легко проверить и при необходимости исправить сторнированием.","q":["как оспорить счёт","оспорить счет","неправильный счёт","не согласен со счётом","ошибка в счёте"]},"q104.mp3":{"a":"Да. У каждого пользователя есть личный кабинет с историей заявок, поставок, счетов и платежей.","q":["можно ли посмотреть историю воды","история водопользования","моя история","личный кабинет","история платежей"]},"q105.mp3":{"a":"Долг учитывается на вашем лицевом счёте, отправляются напоминания, а подача воды идёт по правилам оператора, пока долг не погашен.","q":["что будет если я не заплачу","если не платить","неоплата","не оплатил счёт"]},"q106.mp3":{"a":"Само приложение фермера бесплатное. Фермеры платят только за фактически потреблённую воду.","q":["сколько стоит приложение для фермера","приложение платное","бесплатное ли приложение","приложение фермера","платит ли фермер за приложение"]},"q107.mp3":{"a":"Гидромодульный район объединяет земли по климату и почвам, поэтому у каждого района свои нормы воды для культур, и план использует их, чтобы точно рассчитать, сколько воды нужно каждому участку.","q":["что такое гидромодульный район","гидромодульный район","гидромодуль","гидромодульная зона","что такое гидромодуль"]},"q108.mp3":{"a":"Нетто-норма — это то, что нужно культуре на поле. Мы делим её на КПД системы и получаем брутто-норму подачи, которая учитывает потери при транспортировке.","q":["как считается нетто и брутто норма","нетто и брутто","нетто норма","брутто норма","кпд системы"]},"q109.mp3":{"a":"Водопотребление культур и эвапотранспирация берутся из спутниковых данных FAO WaPOR, которые обновляются каждые десять дней по всей территории.","q":["как измеряется эвапотранспирация","эвапотранспирация","испарение","водопотребление культур","wapor"]},"q110.mp3":{"a":"Спрос прогнозируется по культуре, площади и норме района для каждого участка в сочетании с прогнозами погоды на основе ИИ и пересчитывается при изменении условий.","q":["как прогнозируется спрос на воду","прогноз спроса","прогноз потребности в воде","прогноз погоды"]},"q111.mp3":{"a":"Да. Система управляет лицензиями на скважины, счётчиками на скважинах и уровнями подземных вод, а также распределяет очищенную и повторно используемую воду наряду с поверхностной.","q":["может ли система управлять скважинами и подземными водами","скважины","подземные воды","учёт скважин"]},"q112.mp3":{"a":"Да. Датчики отслеживают показатели качества, например солёность, а для питьевой воды система отмечает показания, выходящие за безопасные пределы.","q":["вы контролируете качество воды","качество воды","солёность воды","мониторинг качества воды"]},"q113.mp3":{"a":"Таблицы не умеют измерять воду в реальном времени, ловить утечку ночью или останавливать хищения. Aquora автоматизирует график, начисляет по реальным объёмам и ведёт полный журнал аудита — на бумаге так нельзя.","q":["почему не использовать таблицы","почему не excel","зачем если есть excel","таблицы excel","чем лучше эксель"]},"q114.mp3":{"a":"Система рассчитана на это. Локальные контроллеры и мобильное приложение работают офлайн и автоматически синхронизируются при восстановлении связи.","q":["что если в сёлах плохой интернет","плохой интернет в деревне","слабая связь","в кишлаке нет интернета"]},"q115.mp3":{"a":"Фермеры общаются простым голосом на своём языке с обычного телефона и быстро видят пользу, когда вода приходит вовремя, а счета справедливые.","q":["что если фермеры против технологий","фермеры не хотят технологии","сопротивление фермеров","фермеры не умеют пользоваться"]},"q116.mp3":{"a":"ИИ только советует. Всё физическое подтверждает человек, каждое решение записывается и объяснимо, а обучен ИИ на измеренных данных, а не на догадках.","q":["ии предвзят или ненадёжен","надёжен ли ии","предвзятость ии","можно ли верить ии"]},"q117.mp3":{"a":"Данные шифруются, доступ ролевой с двухфакторной аутентификацией, всё записывается в журнал, а платформа следует строгим практикам безопасности, чтобы предотвращать утечки данных и ограничивать их последствия.","q":["что насчёт утечки данных","утечка данных","взлом базы","слив данных"]},"q118.mp3":{"a":"Каждый страновой пакет задаёт свою валюту, тарифы и платёжные каналы, поэтому начисления и платежи работают в местной валюте.","q":["как вы работаете с разными валютами","валюта","местная валюта","какие валюты поддерживаются","мультивалютность"]},"q119.mp3":{"a":"Команда объединяет экспертизу в водном хозяйстве, разработке ПО и ИИ, с опытом реальных внедрений в ирригации и коммунальной сфере.","q":["кто в команде","команда","кто работает в команде","ваша команда"]},"q120.mp3":{"a":"Ваше право на использование оросительной воды основано на договоре водоснабжения и праве на воду, записанном в вашем профиле, вместе с документами о собственности или аренде земли — всё это хранится в вашей карточке водопользователя.","q":["на каких документах основано моё право на воду","на каких документах основано мое право на использование оросительной воды","право на воду","документы на воду","какие у меня документы на воду"]},"q121.mp3":{"a":"В профиле указана общая орошаемая площадь ваших участков. В этом демо у водопользователя 1041 три участка общей площадью 4 га.","q":["какая общая площадь моего орошаемого участка","общая площадь моих участков","площадь участка","сколько у меня гектаров","мои участки"]},"q122.mp3":{"a":"Ваши культуры записаны по каждому участку с датами посева — например, хлопок на одном участке и пшеница на другом, — и культура задаёт норму воды для каждого участка.","q":["какие культуры я выращиваю","мои культуры","что я сею","что у меня посеяно"]},"q123.mp3":{"a":"Система сравнивает заявленную площадь со спутниковыми снимками фактически орошаемой территории и отмечает любой участок, где орошаемая площадь не совпадает с документами.","q":["совпадает ли фактически орошаемая площадь с документами","фактическая площадь полива","площадь по документам и по факту","сверка площади со спутником"]},"q124.mp3":{"a":"Система сверяет ваши поставки с утверждённым планом и нормами и показывает, используете ли вы воду в рамках согласованных требований.","q":["использую ли я оросительную воду по требованиям","соблюдаю ли я нормы воды","использую ли я воду по нормам","превышаю ли я норму"]},"q125.mp3":{"a":"Ваш декадный график полива — на экране плана, и система показывает, совпадает ли фактический полив с запланированными очередями.","q":["соблюдаю ли я график полива","мой график полива","соблюдение графика полива","поливаю ли я по графику"]},"q126.mp3":{"a":"Ваши поставки измеряются в реальном времени, поэтому система показывает точный объём воды, полученный вами в этом сезоне.","q":["сколько оросительной воды я получаю","сколько воды я получил","мой объём воды","сколько воды мне подали"]},"q127.mp3":{"a":"Вода выделяется под культуры и участки из вашей заявки, а система отмечает любое использование, не соответствующее согласованному назначению.","q":["использую ли я поливную воду только по назначению","использую ли я воду по назначению","нецелевое использование воды","на что можно использовать поливную воду"]},"q128.mp3":{"a":"Система хранит, на каких ваших подключениях стоят счётчики. Где счётчик установлен, расход измеряется в реальном времени, в остальных случаях показания снимаются вручную.","q":["есть ли счётчики воды на моём участке","есть ли приборы учёта воды на моём участке","стоит ли у меня счётчик воды","как учитывается вода на моём участке"]},"q129.mp3":{"a":"Система ведёт водный баланс вашего участка и показывает, теряется ли вода и где можно повысить эффективность.","q":["принимаю ли я меры против потерь воды","как предотвратить потери воды","теряется ли вода на моём участке","как сократить потери воды"]},"q130.mp3":{"a":"Каждая обнаруженная утечка на вашем канале фиксируется. Вы можете сообщить о новой, после чего система отметит задвижку и уведомит оператора.","q":["обнаружил ли я утечки на оросительных каналах","есть ли утечки на моём канале","как сообщить об утечке","утечка на канале"]},"q131.mp3":{"a":"Если ваш участок делит канал или лимит с другими водопользователями, система показывает общий график и долю каждого.","q":["делю ли я поливную воду с другими водопользователями","делю ли я воду с соседями","общий канал с другими пользователями","какая у меня доля воды"]},"q132.mp3":{"a":"В истории платежей видна каждая оплата и её дата, поэтому сразу понятно, платите ли вы вовремя.","q":["вовремя ли я плачу за подачу воды","плачу ли я вовремя за воду","история платежей","мои платежи за воду"]},"q133.mp3":{"a":"Лицевой счёт показывает задолженность, если она есть. Она появляется только после подачи воды и подписания акта приёма воды.","q":["есть ли у меня долг за воду","есть ли у меня задолженность за воду","мой долг за водоснабжение","сколько я должен за воду"]},"q134.mp3":{"a":"Да. Каждый платёж записан на вашем лицевом счёте с суммой, способом и датой — это и есть подтверждение.","q":["могу ли я подтвердить свои платежи за воду","как доказать что я оплатил воду","подтверждение оплаты воды","где посмотреть квитанцию об оплате"]},"q135.mp3":{"a":"В реестре объектов хранится состояние и история обслуживания канала, который питает ваш участок, поэтому его состояние всегда видно.","q":["в хорошем ли состоянии внутрихозяйственный канал моего участка","в каком состоянии мой канал","состояние канала на моём участке","исправен ли мой канал"]},"q136.mp3":{"a":"Внутрихозяйственные каналы обычно обслуживает ассоциация водопользователей или владелец, а система хранит, кто отвечает за каждый участок канала.","q":["кто отвечает за очистку и обслуживание канала на моём участке","кто чистит канал","кто обслуживает мой канал","кто отвечает за канал"]},"q137.mp3":{"a":"Любое повреждение или засор можно зафиксировать с фото в полевом приложении, и система ведёт его как задачу на обслуживание.","q":["нашёл ли я повреждения или засоры оросительных сооружений","как сообщить о засоре канала","повреждение оросительного сооружения","засор на канале"]},"q138.mp3":{"a":"Ваши сообщения сохраняются с датой и фото и направляются в ответственную организацию, так что видно, что их получили.","q":["сообщил ли я о неисправностях в ответственные организации","куда сообщить о неисправности","получили ли моё сообщение о неисправности","как сообщить о поломке"]},"q139.mp3":{"a":"Ваше участие в очистке и обслуживании можно отметить на вашем счёте и в плане ассоциации водопользователей.","q":["участвую ли я в обслуживании оросительной сети","участие в очистке каналов","как отметить моё участие в обслуживании","участвую ли я в ремонте каналов"]},"q140.mp3":{"a":"Самовольный забор воды выявляется сравнением данных счётчиков и расхода в канале со спутниковыми признаками полива и передаётся на проверку.","q":["брал ли я воду без разрешения","самовольный забор воды","как выявляют хищение воды","незаконный забор воды"]},"q141.mp3":{"a":"Споры о распределении воды фиксируются, а поскольку план и факт подачи записываются по каждому каналу, их можно разрешить по данным.","q":["были ли у меня споры с другими водопользователями из за воды","спор о распределении воды","конфликт из за воды с соседом","как решить спор о воде"]},"q142.mp3":{"a":"Экран диспетчеризации сравнивает плановую и фактическую подачу и показывает, получили ли вы воду в свои очереди по графику.","q":["получаю ли я воду по графику","подают ли мне воду по графику","когда моя очередь полива","пришла ли вода по графику"]},"q143.mp3":{"a":"О проблемах вроде низкого напора или пропущенной очереди можно сообщить через ассистента — они фиксируются, и оператор принимает меры.","q":["какие у меня проблемы с получением поливной воды","проблемы с подачей воды","низкий напор воды","пропустили мою очередь полива"]},"q144.mp3":{"a":"Ваши предложения можно записать, и вместе с отчётами о потерях и о плане и факте они помогают руководству улучшать оросительную систему.","q":["какие меры нужны для улучшения оросительной системы","как улучшить оросительную систему","мои предложения по ирригации","куда отправить предложение"]},"q145.mp3":{"a":"Панель — это вся страна с одного взгляда: активные счета, вода, поданная сегодня, сколько собрано оплат и сколько воды потеряно, всё в реальном времени.","q":["панель","дашборд","что такое дашборд","покажи дашборд","расскажи про панель","что на главной панели"]},"q146.mp3":{"a":"Водопользователи. Здесь зарегистрировано каждое хозяйство и домохозяйство с его участками и площадью. Добавить человека может оператор, или он регистрируется сам голосом.","q":["водопользователи","пользователи","покажи водопользователей","кто такие водопользователи","что такое раздел водопользователи"]},"q147.mp3":{"a":"Культуры и сев. По каждому участку мы записываем культуру и дату сева, потому что культура задаёт норму воды, а план следует севообороту.","q":["культуры","культуры и сев","открой культуры","что такое культуры и сев","расскажи про посевы"]},"q148.mp3":{"a":"Карта и каналы. Вся сеть — водохранилище, магистральный канал, его ответвления, затворы и участки — показана живыми слоями с расходом каждого канала и положением затворов.","q":["карта","карта и каналы","расскажи про карту","что такое карта и каналы","покажи каналы на карте"]},"q149.mp3":{"a":"Заявки. Водопользователь просит воду голосом или кнопкой, и система превращает заявку в десятидневный план полива.","q":["заявки","открой заявки","что такое заявки","расскажи про заявки","как работают заявки на воду"]},"q150.mp3":{"a":"План полива. По норме воды каждой культуры система строит десятидневный график на сезон и сообщает каждому фермеру, когда и сколько поливать.","q":["полив","план полива","открой план полива","что такое план полива","как строится график полива"]},"q151.mp3":{"a":"Лимиты воды. Каждая зона получает сезонный лимит, который сверяется с реальным спросом, поэтому руководство всегда знает, сколько воды ещё доступно.","q":["лимиты","лимиты воды","что такое лимиты","что такое лимиты воды","сколько воды осталось по лимиту"]},"q152.mp3":{"a":"Датчики. Вся сеть измеряется в реальном времени: питьевая вода на входе, стоки на выходе, полив, а также расход и уровни в каналах и влажность почвы. Это позволяет находить утечки и автоматически управлять задвижками.","q":["датчики","покажи датчики","расскажи про датчики","что показывают датчики","что такое датчики"]},"q153.mp3":{"a":"Мелиорация защищает землю. Датчики отслеживают засоление почвы и грунтовые воды по зонам, и при накоплении солей система назначает промывные поливы и дренаж.","q":["мелиорация","что такое мелиорация","расскажи про мелиорацию","засоление почвы","промывные поливы"]},"q154.mp3":{"a":"Диспетчеризация. Операторы видят ежедневное распределение воды по каждому каналу, план и факт, поэтому любая нехватка видна сразу.","q":["диспетчеризация","диспетчер","что такое диспетчеризация","покажи диспетчеризацию","план и факт подачи воды"]},"q155.mp3":{"a":"Начисления. Суммы рассчитываются по реальному измеренному объёму после подписания акта приёма воды, никогда не на глаз, а счета автоматически отправляются по почте.","q":["начисления","биллинг","что такое начисления","объясни начисления","как выставляются счета"]},"q156.mp3":{"a":"Платежи. Водопользователи платят с телефона через банк, а система автоматически сверяет каждый платёж и гасит долг в реальном времени.","q":["платежи","оплата","покажи платежи","что такое платежи","как работают платежи"]},"q157.mp3":{"a":"Отчёты. Любой срез — заявки, водный баланс, план и факт, сборы и потери — можно отфильтровать и выгрузить в Excel или PDF в один клик.","q":["отчёты","что такое отчёты","покажи отчёты","какие есть отчёты","выгрузка в excel"]},"q158.mp3":{"a":"Выявление потерь и хищений. Мы сравниваем водный баланс каждого канала со спутниковыми признаками полива на участках без лимита и даём инспекторам ранжированный список подозрительных случаев.","q":["потери и хищения","потери","хищение воды","что такое потери и хищения","объясни потери","как выявляют хищения"]},"q159.mp3":{"a":"Полевые проверки. Офлайн-приложение для инспекторов и ремонтных бригад: задачи, фото, акты нарушений и электронная подпись, с синхронизацией после восстановления связи.","q":["полевые проверки","инспекции","что такое полевые проверки","объясни полевые проверки","приложение для инспекторов"]},"q160.mp3":{"a":"Обслуживание. Плановые и аварийные работы на каналах и насосах с запчастями, затратами и графиками очистки, чтобы сеть оставалась в хорошем состоянии.","q":["обслуживание","ремонт","открой обслуживание","что такое обслуживание","техобслуживание каналов"]},"q161.mp3":{"a":"Советы фермеру. Персональные рекомендации в WhatsApp или голосом, например: полейте участок 3 в четверг, 900 м³, а если ожидается дождь — пропустите следующую очередь.","q":["советы","советы фермеру","что такое советы","объясни советы","рекомендации по поливу"]},"q162.mp3":{"a":"Климатическая и донорская отчётность. Мы измеряем и подтверждаем сэкономленную воду и энергию и готовим отчёты для доноров и климатических фондов с возможностью получать водные или углеродные кредиты.","q":["климат","климат и доноры","что такое климат и доноры","донорская отчётность","углеродные кредиты"]},"q163.mp3":{"a":"Финансовые услуги. С явного согласия фермера история водопользования передаётся банкам и страховщикам для кредитного скоринга и страхования от засухи. Это новый источник дохода.","q":["финансовые услуги","финансы","что такое финансовые услуги","объясни финансовые услуги","страхование от засухи"]},"q164.mp3":{"a":"Повторное использование и подземные воды. Для стран Персидского залива мы ведём лицензии на скважины, счётчики скважин и распределение очищенной и восстановленной воды для ферм и озеленения.","q":["повторное использование","подземные воды","повторное использование и подземные воды","объясни повторное использование воды","скважины"]},"q165.mp3":{"a":"Трансграничный бассейн. Общий водный баланс для стран одного речного бассейна — Центральной Азии, Нила или водоносных горизонтов Залива, — чтобы стороны, делящие реку, могли доверять цифрам.","q":["бассейн","трансграничный бассейн","что такое трансграничный бассейн","объясни трансграничный бассейн","общий водный баланс стран"]},"q166.mp3":{"a":"Слой ИИ. Шесть агентов выполняют реальную работу: ассистент фермера, копилоты для ассоциации и диспетчера, аналитик министерства, агент аномалий и ИИ для документов. Каждое физическое действие подтверждает человек.","q":["ии","слой ии","что такое слой ии","искусственный интеллект","какие есть ии агенты","что такое ai"]},"q167.mp3":{"a":"Данные и спутники. Водопотребление культур — из FAO WaPOR, снимки — Sentinel-2 и Landsat, картирование культур — Prithvi и AlphaEarth, погода — ECMWF, а речь — более чем на 1600 языках.","q":["данные и спутники","спутники","расскажи про данные и спутники","какие данные вы используете","откуда спутниковые данные"]},"q168.mp3":{"a":"Возможности платформы. Страновые пакеты настраивают язык, тарифы, платежи и законодательство без кода; плюс открытый API, права по ролям, офлайн-приложение, полный журнал аудита и надёжная защита.","q":["платформа","что такое платформа","возможности платформы","что умеет платформа","страновой пакет"]},"q169.mp3":{"a":"Соответствие требованиям. Aquora создана под правила ЕС: NIS2, Закон о киберустойчивости, Закон об ИИ, право на доступ к данным датчиков по Закону о данных и GDPR с согласием на голос.","q":["соответствие","комплаенс","что такое соответствие требованиям","объясни комплаенс","gdpr","соответствует ли aquora правилам ес"]},"q170.mp3":{"a":"Заметки экспертов. Рекомендации наших экспертов по праву, финансам, рынку и языкам: о ручном управлении задвижками, законах о торговле квотами, быстрой выручке и встраивании перевода с первого дня.","q":["эксперты","заметки экспертов","что такое заметки экспертов","объясни заметки экспертов","что говорят эксперты"]},"q171.mp3":{"a":"Дорожная карта. Рабочее ядро и выявление потерь — за шесть месяцев, слой ИИ и спутниковые данные — к двенадцати, открытый маркетплейс и бассейновый вид — к двадцати четырём.","q":["дорожная карта","роадмап","что такое дорожная карта","объясни дорожную карту","какие планы развития"]},"q173.mp3":{"a":"Да. Aquora может работать модулем внутри собственного приложения водного ведомства, под его брендом, так что фермерам не нужно ничего устанавливать.","q":["может ли это быть внутри приложения водного ведомства","может ли aquora работать внутри нашего приложения","может ли аквора работать внутри нашего приложения","можно ли встроить в наше приложение","под нашим брендом"]},"q174.mp3":{"a":"На первый пилотный сезон мы ставим цели: на 20% меньше потерь в каналах, на 30% больше своевременных платежей, 70% заявок с телефона и на 40% меньше бумажной работы диспетчера. Это цели, а не измеренные результаты.","q":["какие цели пилота","каких результатов ждать от пилота","цели пилотного проекта","что даст пилот"]},"q175.mp3":{"a":"Да. Просто скажите, например: «Мне нужна вода для участка три в четверг», и приложение подготовит заявку, которую вы подтвердите одним касанием.","q":["можно ли подать заявку на воду голосом","как заказать воду с телефона","заявка голосом","как попросить воду в приложении"]},"q176.mp3":{"a":"Да. Приложение сохраняет ваши действия офлайн и автоматически синхронизирует их, как только появляется связь.","q":["работает ли приложение без интернета","работает ли приложение офлайн","приложение без связи","что если нет интернета"]},"q177.mp3":{"a":"Оно работает на Android и iPhone, а фермеры с простым телефоном могут пользоваться голосовым звонком или USSD.","q":["есть ли приложение на android и iphone","какие телефоны поддерживает приложение","работает ли на айфоне","а если у фермера простой телефон"]},"q179.mp3":{"a":"Для фермера это минуты, а не недели. Заявка сразу становится планом, акт подписывается, когда приходит вода, а платёж сверяется автоматически.","q":["как быстро проходит весь цикл","сколько времени от заявки до оплаты","как долго от заявки до оплаты","скорость цикла"]},"q180.mp3":{"a":"Начисление считается по реальному измеренному объёму из подписанного акта приёма воды, умноженному на тариф. Оно никогда не рассчитывается на глаз.","q":["как приложение считает мой счёт","как рассчитывается начисление","как считается плата за воду","из чего складывается счёт"]},"q181.mp3":{"a":"Вы платите по номеру лицевого счёта через мобильный банк. Платёж сверяется автоматически, и долг гасится сразу.","q":["как оплатить в приложении","как работает оплата с телефона","как заплатить за воду","оплата через мобильный банк"]},"q183.mp3":{"a":"Он сравнивает, сколько гидропост подаёт в голову канала, с тем, что фермеры принимают в подписанных актах, и сверяет это со спутниковыми признаками полива. Когда вода пропадает, он показывает, где именно и почему.","q":["как вы находите куда пропадает вода","как граф находит потери воды","где теряется вода","как найти потери воды"]},"q184.mp3":{"a":"Для каждой связи граф показывает доказательства, толкование ИИ и статус, чтобы человек мог подтвердить или отклонить её. Никакого чёрного ящика.","q":["как граф объясняет свои выводы","что значит почему эта связь","это чёрный ящик","как проверить вывод ии"]},"q185.mp3":{"a":"Нажмите на любой узел или связь, чтобы увидеть доказательства и объяснение, и переключайтесь между примерами: потери в канале, прогноз дождя, ночной скачок или начисления.","q":["можно ли нажимать на граф","как пользоваться водным графом","как работать с графом","что можно делать в графе"]},"q186.mp3":{"a":"Ассоциация водопользователей объединяет хозяйства вдоль канала. В графе каждая ассоциация связывает свой канал со своими участками, поэтому потери и планы можно отследить до нужной группы фермеров.","q":["что такое авп","что такое ассоциация водопользователей","что такое ассоциации водопользователей в графе","авп в графе","что такое wua"]},"q187.mp3":{"a":"Приложение фермера кладёт всю систему в карман фермеру. С одного телефона вы регистрируетесь, видите свои участки, культуры и лицевой счёт и заказываете воду просто голосом. Приложение строит ваш график полива, показывает поступление воды с датчиков в реальном времени и позволяет подписать акт приёма воды одним касанием. Вы видите каждое начисление, рассчитанное по реальному измеренному объёму, и платите по номеру лицевого счёта через мобильный банк. Вы следите за сезонным лимитом и полной историей заявок, подач и платежей. Вы получаете оповещения об утечках и дожде, можете закрыть или открыть домашний кран и приостановить подачу воды на время отъезда. Можно отправить жалобу, получить совет в WhatsApp или голосом, приложение работает офлайн и даже с простого телефона по голосовому звонку. Так фермер управляет всей своей частью системы с телефона.","q":["приложение фермера","мобильное приложение","расскажи про мобильное приложение","что умеет приложение фермера","что такое приложение фермера"]},"q188.mp3":{"a":"Путь в приложении — это весь водный цикл на одном телефоне, в семь шагов. Первый — заявка: фермер просит воду голосом или касанием. Второй — план: Aquora проверяет сезонный лимит и превращает заявку в десятидневный график полива по норме воды культуры, а при прогнозе дождя сама пропускает очередь. Третий — подача: затвор открывается, и фермер видит, как вода приходит, по данным датчика в реальном времени. Четвёртый — акт приёма воды: фермер подтверждает измеренный объём электронной подписью. Пятый — начисление: по этому реальному объёму и тарифу, никогда не на глаз. Шестой — оплата: по номеру лицевого счёта через мобильный банк, с автоматической сверкой, и долг гасится сразу. И седьмой — поддержка: советы в WhatsApp или голосом, оповещения об утечках и дожде и жалобы, которые отслеживаются до решения. От заявки до закрытого счёта — минуты, а не недели.","q":["путь в приложении","путь пользователя","покажи путь в приложении","что такое путь в приложении","шаги в приложении"]},"q189.mp3":{"a":"Водный граф — это мозг приложения. Он объединяет всё в одну живую сеть: речной бассейн и водохранилище, магистральный канал и его ответвления, ассоциации водопользователей, каждый участок, гидропосты и датчики, спутниковые и погодные данные, а также деньги — от актов приёма воды до начислений и платежей. Поскольку всё связано, Aquora видит причины и следствия. Например, она сравнивает, сколько гидропост подаёт в голову канала, с тем, что фермеры принимают в подписанных актах, и сверяет это со спутниковыми признаками полива. Когда вода пропадает, граф подсвечивает, какой именно канал и какие участки, а панель «Почему эта связь» показывает доказательства, толкование ИИ и статус. Так же это работает для прогноза дождя, который отменяет очередь полива, ночного скачка, который закрывает задвижку, или счёта, который следует за подписанным актом. Каждый вывод человек подтверждает или отклоняет, поэтому никакого чёрного ящика.","q":["водный граф","граф","что такое водный граф","что показывает водный граф","расскажи про граф"]},"q190.mp3":{"a":"Это ROI-калькулятор. Выберите культуру, задайте орошаемую площадь, стоимость воды и ожидаемую экономию воды за счёт графиков и контроля потерь. Калькулятор сразу показывает, сколько воды и денег экономится в год, сколько стоит Aquora, чистую выгоду и за сколько месяцев она окупается. Это ваши цифры и ваши допущения, а не измеренные результаты, поэтому инвестор или министерство могут проверить любой сценарий за секунды.","q":["roi калькулятор","калькулятор","что такое roi калькулятор","калькулятор окупаемости","что такое калькулятор окупаемости"]},"q191.mp3":{"a":"Это зависит от вашей сети, поэтому откройте ROI-калькулятор и задайте площадь, стоимость воды и ожидаемую экономию. Он покажет окупаемость в месяцах и кратность возврата. При консервативных вводных, например 10% сэкономленной воды по два цента за м³, затраты на внедрение окупаются в первый же год. Это иллюстративные цифры по вашим вводным, а не измеренные результаты.","q":["окупаемость","какой срок окупаемости","за сколько окупится","какой roi и окупаемость","когда окупится aquora","когда окупится аквора"]},"q192.mp3":{"a":"Экономия складывается из трёх источников: график полива по реальной потребности культур вместо фиксированных очередей, раннее выявление утечек и хищений и начисления по измеренным объёмам, чтобы оплачивалась большая часть поданной воды. Калькулятор учитывает только сэкономленную воду, поэтому остаётся консервативным.","q":["как aquora экономит воду","как аквора экономит воду","откуда берётся экономия","за счёт чего экономия","как экономится вода"]},"q193.mp3":{"a":"Нет. Калькулятор иллюстративный. Он перемножает ваши собственные вводные: площадь, воду на гектар, стоимость воды и ожидаемую экономию. Реальные цифры дают измерения в пилоте — именно для этого и нужен первый сезон.","q":["реальные ли цифры roi","это реальные цифры","калькулятор на реальных данных","цифры калькулятора настоящие"]},"q194.mp3":{"a":"Цена устанавливается по стране и по модулям. В калькуляторе можно ввести любую подписку на гектар и любые разовые затраты на внедрение и сразу увидеть, как это меняет окупаемость.","q":["сколько стоит за гектар","сколько стоит aquora за гектар","сколько стоит аквора за гектар","какая цена за гектар","стоимость на гектар"]},"q195.mp3":{"a":"Это симулятор засухи. Двигайте ползунок, чтобы урезать воду в канале, например до 70% от плана. При равном урезании каждое хозяйство теряет одинаковую долю, и сильнее всего страдают ценные культуры — виноградники и томаты. С ИИ Aquora каждый участок сначала сохраняет не меньше половины своей воды, а остаток идёт туда, где каждый м³ спасает больше урожая, по коэффициентам реакции урожая FAO. При 70% ИИ сокращает потери урожая почти вдвое. Окончательное распределение всегда утверждает водное ведомство.","q":["симулятор засухи","засуха","что такое симулятор засухи","как работает симулятор засухи","расскажи про симулятор засухи"]},"q196.mp3":{"a":"Сначала каждый участок получает минимум для выживания — половину своей воды, так что ни один фермер не остаётся без воды. Затем оставшаяся вода шаг за шагом идёт культурам, где один дополнительный м³ сохраняет больше всего стоимости урожая. Для этого используется коэффициент реакции урожая FAO, который показывает, насколько резко падает урожай культуры при нехватке воды.","q":["как ии распределяет воду","как ии решает кому дать воду","как ии делит воду в засуху","по какому принципу распределяется вода"]},"q197.mp3":{"a":"Да. Никто не остаётся без воды, каждый участок сохраняет минимум половину своей воды, правила прозрачны, а окончательный план утверждает водное ведомство. Фермеры видят в приложении свой лимит и его обоснование.","q":["справедливо ли это для фермеров","справедлив ли ии","справедливо ли распределение в засуху","не обидят ли фермеров"]},"q198.mp3":{"a":"Это коэффициент из публикации FAO по орошению и дренажу № 33. Он показывает, насколько падает урожай культуры при данной нехватке воды. Например, кукуруза с 1,25 очень чувствительна, а хлопок с 0,85 более устойчив.","q":["что такое fao 33","что такое фао 33","что такое ky","что такое коэффициент реакции урожая","коэффициент урожайности"]},"q199.mp3":{"a":"Это здоровье посевов из космоса. На реальном спутниковом снимке переключитесь на вегетационный индекс, и каждое поле покажет свою силу роста — от голой почвы коричневым до густых здоровых посевов зелёным. Aquora связывает каждое поле с его водой. Здесь у участка C-07 сила роста падает, а последний полив был одиннадцать дней назад, поэтому система готовит полив в течение 48 часов. Участок E-03 заявлен под хлопок, но выглядит незасеянным, поэтому он отмечен для полевой проверки. В рабочей системе мы используем NDVI с Sentinel-2 примерно раз в пять дней.","q":["здоровье посевов","что такое здоровье посевов","покажи здоровье посевов","состояние посевов","расскажи про здоровье посевов"]},"q200.mp3":{"a":"NDVI — нормализованный разностный вегетационный индекс — сравнивает, насколько сильно растения отражают ближний инфракрасный свет по сравнению с красным. Здоровые густые посевы дают высокое значение, а угнетённые посевы и голая почва — низкое. Спутники Sentinel-2 предоставляют его бесплатно примерно раз в пять дней.","q":["ndvi","что такое ndvi","объясни ndvi","что такое вегетационный индекс","что такое эн ди ви ай"]},"q201.mp3":{"a":"Sentinel-2 пролетает над каждым полем примерно раз в пять дней, если позволяет облачность. Aquora автоматически обновляет силу роста каждого поля и присылает оповещение, когда она падает.","q":["насколько свежие спутниковые данные","как часто приходят новые снимки","как часто обновляется спутниковый снимок","частота обновления снимков"]},"q202.mp3":{"a":"Когда сила роста поля падает, Aquora проверяет его воду: последний полив, датчик влажности почвы и план. Если полю не хватает воды, система готовит полив. Если вода пришла, а сила роста всё равно падает, это указывает на вредителей или болезни, и система предлагает проверку.","q":["как здоровье посевов связано с водой","что происходит когда поле в стрессе","зачем нужно здоровье посевов","что если поле угнетено"]},"q203.mp3":{"a":"Да. Если фермер заявил культуру, а спутник показывает голую почву или другую культуру, поле отмечается для проверки до выделения воды и субсидий.","q":["может ли система проверить заявленное фермером","может ли она обнаружить не ту культуру","может ли она выявить ложные заявления","проверка заявленных культур"]},"q204.mp3":{"a":"Это бизнес-модель. Aquora зарабатывает тремя способами. Первый — регулярная подписка на ПО: годовая лицензия на сеть или на счётчик с тарифами по объёму воды и модулям. Второй — внедрение: интеграция, загрузка данных и настройка. Третий — оборудование и данные: IoT-датчики и счётчики через партнёров, а аналитика и ИИ — как премиальные дополнения. Покупатели — государственные водные ведомства и коммунальные предприятия, агрохолдинги и промышленные водопользователи. Мы заходим с пилота, а затем расширяемся модуль за модулем до национального масштаба.","q":["бизнес модель","что такое бизнес модель","какая у вас бизнес модель","как зарабатывает aquora","как зарабатывает аквора"]},"q205.mp3":{"a":"Большой и востребованный. По данным FAO, около 70% мирового забора пресной воды приходится на сельское хозяйство, а Всемирный банк оценивает, что около 30% поданной воды теряется как неучтённая вода. Наши стартовые рынки — Центральная Азия, Кавказ и Ближний Восток, где высок водный стресс и правительства финансируют водные инновации.","q":["насколько большой рынок","какой размер рынка","какой у вас рынок","объём рынка"]},"q206.mp3":{"a":"Государственные водные ведомства и коммунальные предприятия — по контракту, а также агрохолдинги и промышленные водопользователи, которые платят подписку за свои сети.","q":["кто ваши клиенты","кто покупает aquora","кто покупает аквору","кто платит за aquora","кто платит за аквору"]},"q207.mp3":{"a":"Да. Основа — годовая подписка, а каждый новый модуль, счётчик или регион увеличивает тот же контракт, поэтому выручка растёт по мере расширения клиента.","q":["это подписка","это регулярная выручка","выручка повторяющаяся","модель подписки"]},"q208.mp3":{"a":"Мы начинаем с пилота с измерениями на одной сети, превращаем его в базовую лицензию, затем добавляем модули — ИИ, датчики, финансовые услуги — и расширяемся регион за регионом до национального масштаба.","q":["как вы растёте","что такое land and expand","как вы выходите на рынок","стратегия выхода на рынок","как вы расширяетесь"]},"q209.mp3":{"a":"На живой карте пронумерованные метки отмечают подозрительные точки. Случай один, на канале два, — участок, который поливается без лимита. Случай два, на канале пять, — поле зеленеет без заявки на воду. Случай три, у водозабора магистрального канала, — расход превышает измеренную подачу. Инспекторы получают этот ранжированный список в полевом приложении.","q":["покажи утечки на карте","что означают метки на карте","где утечки на карте","что за цифры на карте","подозрительные точки на карте"]},"q210.mp3":{"a":"Выберите основную культуру сверху и двигайте ползунки: орошаемая площадь, вода на гектар, стоимость воды, ожидаемая экономия, а также подписка и затраты на внедрение Aquora. Результаты ниже обновляются мгновенно: сэкономленная вода, её стоимость, затраты, чистая выгода, окупаемость и возврат.","q":["как пользоваться roi калькулятором","как работает roi калькулятор","как пользоваться калькулятором","как работает калькулятор окупаемости"]},"q211.mp3":{"a":"Окупаемость — это сколько месяцев чистой выгоды нужно, чтобы вернуть разовые затраты на внедрение. Чистая выгода — это стоимость сэкономленной воды минус годовая подписка.","q":["как считается окупаемость","что значит окупаемость","что такое окупаемость","что такое чистая выгода"]},"q212.mp3":{"a":"Возврат показывает, сколько долларов стоимости воды Aquora экономит на каждый доллар годовой подписки. «В три раза» значит три доллара экономии на каждый потраченный доллар.","q":["что значит возврат","что значит в три раза","что такое кратность возврата","что значит три икс"]},"q213.mp3":{"a":"Каждой культуре нужно разное количество воды за сезон. Выбор культуры задаёт типичный объём брутто на гектар, например 9 000 м³ для хлопка или 14 000 для риса. Затем его можно уточнить ползунком.","q":["что делают кнопки культур","зачем кнопки культур","зачем выбирать культуру","почему надо выбрать культуру"]},"q214.mp3":{"a":"Это то, сколько для вас стоит один м³: тариф, затраты на перекачку и подачу или стоимость дополнительного урожая, который можно с ним вырастить. Поливная вода часто дешёвая, поэтому калькулятор начинает с двух центов за м³, чтобы оставаться консервативным.","q":["что такое стоимость воды","какую цену воды указать","почему вода такая дешёвая","сколько стоит кубометр воды"]},"q215.mp3":{"a":"Это зависит от сети. Калькулятор начинает с консервативных 10% и позволяет проверить любое значение от 3 до 30%. Реальную цифру измеряют в пилотном сезоне.","q":["сколько воды может сэкономить aquora","сколько воды может сэкономить аквора","реалистичны ли десять процентов","какую экономию ожидать"]},"q216.mp3":{"a":"Это разовые затраты на внедрение: интеграция, загрузка данных и настройка странового пакета. В калькуляторе они задаются на гектар и определяют срок окупаемости.","q":["что входит в затраты на внедрение","что такое разовое внедрение","что такое затраты на внедрение","сколько стоит внедрение"]},"q217.mp3":{"a":"Если годовые затраты выше стоимости сэкономленной воды, чистая выгода становится красной, и калькулятор сообщает, что при этих вводных окупаемости нет. Так вы видите и слабые сценарии, а не только удачные.","q":["может ли aquora быть убыточной","может ли аквора быть убыточной","что если не окупится","что если чистая выгода отрицательная"]},"q218.mp3":{"a":"Калькулятор делит сэкономленную воду на воду на гектар. При экономии 10% на 5 000 га это примерно 500 га, которые можно дополнительно оросить, — или вода может просто остаться в реке.","q":["сколько ещё гектаров можно оросить","что делать со сэкономленной водой","что значит дополнительные гектары","дополнительная площадь полива"]},"q219.mp3":{"a":"Ползунок площади идёт от 500 до 50 000 га, поэтому охватывает всё — от одной ассоциации водопользователей до целого бассейна.","q":["можно ли изменить площадь","какую площадь можно рассчитать","какую площадь можно ввести","максимальная площадь в калькуляторе"]},"q220.mp3":{"a":"Нет. Он учитывает только стоимость сэкономленной воды, поэтому остаётся консервативным. Дополнительная выручка от начислений по реальным измеренным объёмам будет сверху.","q":["учитывает ли калькулятор экономию на начислениях","учитывает ли он сбор оплаты","учитывает ли калькулятор дополнительную выручку","входит ли выручка от биллинга"]},"q221.mp3":{"a":"Двигайте ползунок, чтобы задать, сколько воды доступно относительно плана, от 50 до 100%. Затем переключайтесь между «ИИ Aquora» и «Равным урезанием», чтобы сравнить. Карточки сверху показывают потерю урожая в каждом варианте и сколько экономит ИИ.","q":["как пользоваться симулятором засухи","как работает симулятор засухи","как управлять симулятором засухи","что делает ползунок в симуляторе"]},"q222.mp3":{"a":"Равное урезание — так часто справляются с нехваткой сегодня: каждое хозяйство теряет одинаковую долю воды, что бы оно ни выращивало. Это просто, но сильнее всего бьёт по ценным и чувствительным культурам.","q":["что значит равное урезание","что такое равное урезание","что такое равное сокращение","равное урезание воды"]},"q223.mp3":{"a":"Потому что они теряют больше всего стоимости на каждый недостающий м³. Виноградники и томаты стоят гораздо дороже с гектара, поэтому каждый м³ там спасает больше урожая.","q":["почему некоторые культуры получают всю воду","почему томаты получают всю воду","почему виноградник получает всю воду","почему виноград без урезания"]},"q224.mp3":{"a":"Пшеница и люцерна приносят меньше стоимости на м³ воды. После того как каждый участок получил свою половину, дополнительная вода идёт сначала культурам, где она сохраняет больше стоимости. Они всё равно сохраняют не меньше половины своей воды, так что никто не остаётся без воды.","q":["почему некоторые культуры получают только половину","почему люцерна получает только половину","почему пшеница получает меньше воды","почему пшенице урезали воду"]},"q225.mp3":{"a":"Пунктирная линия отмечает 50% плана. Это минимум для выживания. Ни один участок не опускается ниже неё.","q":["что значит пунктирная линия","что такое пунктирная линия","что за линия посередине столбцов","что за пунктир на графике"]},"q226.mp3":{"a":"Это доля обычного урожая, которую каждый участок, по расчёту, сохранит при таком количестве воды. Она считается по коэффициенту реакции урожая FAO для его культуры.","q":["что значит сохранённый урожай","что значит процент справа","что такое сохранённый урожай","что за проценты справа"]},"q227.mp3":{"a":"При 70% плана равное урезание теряет около 348 тысяч долларов урожая, а ИИ — около 184 тысяч. Это примерно 164 тысячи долларов экономии, на 47% меньше потерь. Цифры иллюстративные.","q":["сколько экономит ии","сколько урожая спасает ии","сколько денег экономит ии в засуху","какая выгода от ии в засуху"]},"q228.mp3":{"a":"При 50% каждый участок просто получает половину своей воды, потому что это минимум для выживания. ИИ начинает оптимизировать только выше 50%, когда есть дополнительная вода для распределения.","q":["что происходит при пятидесяти процентах","что если в канале половина воды","что если воды только половина","что будет при 50 процентах"]},"q229.mp3":{"a":"Нет. Шесть участков, их площади и цены культур — иллюстративные. Метод настоящий: коэффициенты реакции урожая FAO, которые в рабочей системе применяются к реальным участкам и культурам водного ведомства.","q":["реальные ли участки в симуляторе","это реальные хозяйства","реальные ли данные о засухе","данные симулятора настоящие"]},"q230.mp3":{"a":"ИИ предлагает распределение и объясняет его. Водное ведомство проверяет и утверждает окончательный план, а каждое решение записывается в журнал.","q":["ии решает сам","кто утверждает план на засуху","кто принимает окончательное решение о распределении","кто утверждает распределение воды"]},"q231.mp3":{"a":"Виноградник и кукуруза в АВП «Север», хлопок и пшеница в АВП «Центр», томаты и люцерна в АВП «Восток» — у каждого своя площадь и типичная стоимость урожая.","q":["какие участки в симуляторе засухи","какие культуры в симуляторе","какие хозяйства в симуляторе","что за участки в симуляторе"]},"q232.mp3":{"a":"Двумя кнопками сверху переключайтесь между спутниковым фото и вегетационным индексом. Нажмите на любую метку, чтобы увидеть индекс участка, его культуру, историю полива и рекомендуемое действие. В таблице ниже перечислены все участки.","q":["как пользоваться здоровьем посевов","как работает здоровье посевов","как пользоваться экраном здоровья посевов","как переключить на вегетационный индекс"]},"q233.mp3":{"a":"Зелёный — густая здоровая растительность. Жёлтый — угнетённые или редкие посевы. Коричневый — голая почва. Шкала под картой идёт от голой почвы до здоровых посевов.","q":["что означают цвета","что значат цвета на карте","что значит зелёный","что значит коричневый цвет"]},"q234.mp3":{"a":"Участок C-07 — кукуруза в АВП «Центр». Его индекс около 0,5, это стресс. Последний полив был одиннадцать дней назад, а датчик почвы S7 показывает низкую влажность, поэтому Aquora готовит полив в течение 48 часов.","q":["что за участок c 07","что не так с c 07","почему c 07 в стрессе","участок си семь","что с участком c7"]},"q235.mp3":{"a":"Участок E-03 в АВП «Восток» заявлен под хлопок, но спутник показывает почти голую почву с индексом около 0,2, и в этом сезоне не было заявки на воду. Поэтому он отмечен для полевой проверки.","q":["что за участок e 03","что не так с e 03","почему e 03 отмечен","участок е три","что с участком e3"]},"q236.mp3":{"a":"Участок N-12 с пшеницей и участок N-04 с люцерной, оба в АВП «Север», здоровы — индексы около 0,8. Они идут по графику, поэтому никаких действий не нужно.","q":["что с n 04","что с n 12","какие участки здоровы","участок n12","здоровые участки"]},"q237.mp3":{"a":"Да. Это реальный снимок сельхозугодий из Sentinel Hub, распространяемый по лицензии Creative Commons. Индекс вычисляется в реальном времени прямо в вашем браузере по самому снимку.","q":["спутниковый снимок настоящий","это реальный спутниковый снимок","откуда этот снимок","источник снимка"]},"q238.mp3":{"a":"В этом демо он считается по видимым цветам снимка — зелёный сравнивается с красным и синим. В рабочей системе Aquora использует NDVI с Sentinel-2, который берёт ближний инфракрасный свет и точнее.","q":["как вы считаете вегетационный индекс","как рассчитывается индекс","чем этот индекс отличается от ndvi","откуда берётся индекс в демо"]},"q239.mp3":{"a":"Выше 0,65 поле считается здоровым, от 0,4 до 0,65 — в стрессе, ниже 0,4 — слабым или голым.","q":["какие пороги","когда поле здоровое","когда поле в стрессе","пороги индекса"]},"q240.mp3":{"a":"Облачные снимки пропускаются. Aquora хранит последний чистый снимок, а в промежутках опирается на датчики влажности почвы и данные о воде.","q":["а как же облака","что если поле закрыто облаками","что если облачно","облачность на снимках"]},"q241.mp3":{"a":"Это годовая лицензия на сеть или на счётчик с тарифами по объёму управляемой воды и используемым модулям. Это регулярное ядро нашей выручки.","q":["как работает подписка","что такое лицензия","что такое saas подписка","как устроена лицензия"]},"q242.mp3":{"a":"Внедрение включает интеграцию с существующими системами, загрузку данных — реестров, счётчиков и записей начислений — и настройку странового пакета. Оплачивается за проект.","q":["сколько стоит внедрение","что входит во внедрение","что такое внедрение","как оплачивается внедрение"]},"q243.mp3":{"a":"Мы поставляем IoT-датчики и счётчики через партнёров-производителей оборудования, поэтому не привязаны к одному вендору. Аналитика и ИИ идут как премиальные дополнения к базовой лицензии.","q":["вы делаете датчики","вы продаёте датчики","что такое оборудование и данные","кто поставляет датчики"]},"q244.mp3":{"a":"Пилот — это работа Aquora на одной сети в течение сезона с измеренными результатами. Он доказывает экономию в реальных цифрах и затем переходит в базовую лицензию. Дальше мы добавляем модули, датчики и данные вплоть до национального масштаба.","q":["как работает пилот","что значат пять шагов","что такое пилот","что такое пилотный проект"]},"q245.mp3":{"a":"Центральная Азия, Кавказ, а также Ближний Восток и Северная Африка — одни из самых вододефицитных регионов. Там основная часть воды идёт на орошение, а правительства активно финансируют цифровизацию водного хозяйства. Мы хорошо знаем эти сети.","q":["какие ваши стартовые рынки","почему центральная азия","почему эти рынки","на какие рынки вы выходите"]},"q246.mp3":{"a":"Данные о том, что 70% забора пресной воды идёт на сельское хозяйство, — от FAO. Оценка, что около 30% поданной воды теряется как неучтённая вода, — от Всемирного банка.","q":["какой источник цифр","откуда эти цифры","откуда семьдесят процентов","источник данных о рынке"]},"q247.mp3":{"a":"Государственные ведомства и коммунальные предприятия обычно покупают по контракту: внедрение плюс годовая лицензия, часто начиная с пилота. Донорские и климатические фонды могут софинансировать.","q":["как работают госконтракты","как платит государство","как министерство покупает aquora","как министерство покупает аквору"]},"q248.mp3":{"a":"Каждый клиент растёт от одной сети до региона, а затем до всей страны, добавляя модули и счётчики. Та же платформа переиспользуется и настраивается страновым пакетом, поэтому запуск в каждой новой стране обходится дешевле.","q":["как вы масштабируетесь","как растёт выручка","как вы будете увеличивать выручку","масштабирование"]},"q249.mp3":{"a":"Цены зависят от страны, размера сети и модулей, поэтому мы готовим предложение для каждого клиента. В ROI-калькуляторе можно проверить любой уровень подписки против сэкономленной воды.","q":["сколько стоит лицензия","какие у вас цены","какая цена","сколько стоит aquora","сколько стоит аквора"]},"q250.mp3":{"a":"Белые линии потока показывают движение воды по магистральному каналу и его ответвлениям — каналу два и каналу пять — на реальной аэрофотосъёмке.","q":["какие каналы на карте","что за белые линии на карте","что значит движущаяся вода на карте","что за линии на карте"]},"q251.mp3":{"a":"Разрыв баланса — это насколько меньше воды учтено ниже по течению, чем было подано выше. Минус 38% означает, что более трети воды на этом участке канала не объяснено.","q":["что значит минус тридцать восемь процентов","что значит процент на метке","что такое разрыв баланса","что значит минус 38"]}};
